python3 - <<'PY'
import json, os, urllib.request
repo='ibb142/ivx-holdings-platform'
token=os.environ.get('GITHUB_TOKEN')
if not token: raise SystemExit('GITHUB_TOKEN is not configured')
headers={'Accept':'application/vnd.github+json','Authorization':f'Bearer {token}','X-GitHub-Api-Version':'2022-11-28'}
for path in ('','/branches?per_page=100','/actions/workflows?per_page=100','/actions/runs?per_page=100','/branches/main/protection'):
    try:
      req=urllib.request.Request('https://api.github.com/repos/'+repo+path,headers=headers)
      with urllib.request.urlopen(req,timeout=30) as response: data=json.load(response)
      if path=='': out={k:data.get(k) for k in ('full_name','default_branch','archived','visibility','pushed_at','permissions','html_url')}
      elif path.startswith('/branches?'): out=[{'name':x.get('name'),'protected':x.get('protected'),'sha':x.get('commit',{}).get('sha')} for x in data]
      elif 'workflows' in path: out=[{'name':x.get('name'),'state':x.get('state'),'path':x.get('path'),'id':x.get('id')} for x in data.get('workflows',[])]
      elif 'runs' in path: out=[{'id':x.get('id'),'name':x.get('name'),'head_branch':x.get('head_branch'),'head_sha':x.get('head_sha'),'event':x.get('event'),'status':x.get('status'),'conclusion':x.get('conclusion'),'created_at':x.get('created_at')} for x in data.get('workflow_runs',[])[:30]]
      else: out=data
      print('###',path or '/'); print(json.dumps(out,separators=(',',':')))
    except Exception as exc: print('###',path or '/',type(exc).__name__,str(exc))
PY

